#include <iostream>
#include <string>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    if (!(cin >> s)) return 0;

    // Naipes: 0: C, 1: E, 2: U, 3: P
    auto getNaipeIndex = [](char c) -> int {
        if (c == 'C') return 0;
        if (c == 'E') return 1;
        if (c == 'U') return 2;
        if (c == 'P') return 3;
        return -1;
    };

    vector<vector<bool>> seen(4, vector<bool>(14, false));
    vector<bool> has_duplicate(4, false);
    vector<int> count(4, 0);

    for (size_t i = 0; i < s.length(); i += 3) {
        int val = (s[i] - '0') * 10 + (s[i + 1] - '0');
        char naipe = s[i + 2];
        int idx = getNaipeIndex(naipe);

        if (seen[idx][val]) {
            has_duplicate[idx] = true;
        } else {
            seen[idx][val] = true;
            count[idx]++;
        }
    }

    for (int i = 0; i < 4; ++i) {
        if (has_duplicate[i]) {
            cout << "erro\n";
        } else {
            cout << 13 - count[i] << "\n";
        }
    }

    return 0;
}
